import type { Parser, Tree } from "@lezer/common"
import { highlightTree } from "@lezer/highlight"

import {
  loadParser,
  normalizeLanguage,
  parserFor,
  syntaxHighlighter,
  type CodeLanguage,
  type SyntaxTone,
} from "@/components/ui/code-highlight"
import type { DiffLine } from "@/lib/diff-types"
import type { DiffViewFile } from "@/components/ui/diff-view-model"

type DiffSide = "old" | "new"

/** A syntax tone over `[from, to)` of one line. */
type SyntaxSpan = { from: number; to: number; tone: SyntaxTone }

type SideSource = {
  text: string
  /** Offset of each line in `text`, by line number. */
  starts: Map<number, number>
  tree?: Tree
  parsing?: boolean
  spans: Map<number, readonly SyntaxSpan[]>
}

const languageOf = (file: DiffViewFile) => normalizeLanguage(file.language)

// Parsing yields to the page after this long, so a 20,000-line file never blocks a frame.
const SLICE_MS = 8
const MAX_LINE = 2000

function sourceOf(file: DiffViewFile, side: DiffSide): SideSource {
  const full = side === "old" ? file.oldLines : file.newLines
  const starts = new Map<number, number>()
  const parts: string[] = []
  let offset = 0
  const add = (number: number, text: string) => {
    starts.set(number, offset)
    parts.push(text)
    offset += text.length + 1
  }
  if (full) full.forEach((text, index) => add(index + 1, text))
  else {
    // From a patch alone, a side is the hunks' lines in order: enough context for most constructs.
    for (const hunk of file.diff.hunks) {
      for (const line of hunk.lines) {
        const number = side === "old" ? line.oldLine : line.newLine
        if (number !== undefined && line.kind !== (side === "old" ? "added" : "removed")) add(number, line.text)
      }
    }
  }
  return { text: parts.join("\n"), starts, spans: new Map() }
}

function schedule(task: () => void) {
  if (typeof requestIdleCallback === "function") requestIdleCallback(task, { timeout: 200 })
  else setTimeout(task, 0)
}

function parseInSlices(parser: Parser, source: SideSource, done: () => void) {
  const parse = parser.startParse(source.text)
  const step = () => {
    const end = performance.now() + SLICE_MS
    for (;;) {
      const tree = parse.advance()
      if (tree) {
        source.tree = tree
        done()
        return
      }
      if (performance.now() > end) break
    }
    schedule(step)
  }
  schedule(step)
}

/**
 * Syntax tones for the lines a diff shows, made only when a line renders: each side of a file parses once, in
 * slices between frames, the first time one of its lines is on screen, and each line is highlighted from the
 * tree on its own. `onReady` runs when a parse finishes, so the visible rows can render again in colour; only the
 * rows of a file whose `version` changed need to.
 */
function createDiffSyntax(onReady: () => void) {
  const sources = new WeakMap<DiffViewFile, Partial<Record<DiffSide, SideSource>>>()
  const versions = new WeakMap<DiffViewFile, number>()
  const pendingLanguages = new Set<CodeLanguage>()
  let epoch = 0
  let disposed = false

  const ready = (file?: DiffViewFile) => {
    if (disposed) return
    if (file) versions.set(file, (versions.get(file) ?? 0) + 1)
    else epoch++
    onReady()
  }

  function source(file: DiffViewFile, side: DiffSide) {
    let entry = sources.get(file)
    if (!entry) {
      entry = {}
      sources.set(file, entry)
    }
    entry[side] ??= sourceOf(file, side)
    return entry[side]
  }

  function startParse(file: DiffViewFile, side: DiffSide, entry: SideSource) {
    const language = languageOf(file)
    const parser = parserFor(language)
    if (!parser) {
      if (pendingLanguages.has(language)) return
      pendingLanguages.add(language)
      loadParser(language).then(
        () => {
          pendingLanguages.delete(language)
          ready()
        },
        () => {},
      )
      return
    }
    entry.parsing = true
    parseInSlices(parser, entry, () => ready(file))
  }

  /** The tones of a line, `null` while its side parses, `[]` for a language without a parser. */
  function spans(file: DiffViewFile, line: DiffLine, side: DiffSide): readonly SyntaxSpan[] | null {
    const language = languageOf(file)
    if (language === "plaintext" || language === "diff" || language === "bash" || language === "sh") return []
    if (line.text.length > MAX_LINE) return []
    const number = side === "old" ? line.oldLine : line.newLine
    if (number === undefined) return []
    const entry = source(file, side)
    const cached = entry.spans.get(number)
    if (cached) return cached
    if (!entry.tree) {
      if (!entry.parsing) startParse(file, side, entry)
      return null
    }
    const from = entry.starts.get(number)
    if (from === undefined) return []
    const to = from + line.text.length
    const out: SyntaxSpan[] = []
    highlightTree(
      entry.tree,
      syntaxHighlighter,
      (start, end, classes) => {
        const tone = classes.split(" ")[0] as SyntaxTone
        out.push({ from: Math.max(start, from) - from, to: Math.min(end, to) - from, tone })
      },
      from,
      to,
    )
    entry.spans.set(number, out)
    return out
  }

  return {
    spans,
    /** Changes when a parse of this file finishes or a parser loads. */
    version: (file: DiffViewFile) => epoch * 1_000_000 + (versions.get(file) ?? 0),
    dispose() {
      disposed = true
    },
  }
}

type DiffSyntax = ReturnType<typeof createDiffSyntax>

export { createDiffSyntax }
export type { DiffSide, DiffSyntax, SyntaxSpan }

import { pairLines } from "@/lib/diff-intraline"
import { splitLines } from "@/lib/diff-lines"
import type { DiffHunk, DiffLine, FileDiff } from "@/lib/diff-types"

type DiffLayout = "unified" | "split"

type DiffNotice = "binary" | "too-large" | "unchanged"

/** A run of unchanged lines between hunks (or before the first, after the last) that isn't shown yet. */
type DiffGap = {
  id: number
  /** First hidden line on each side, from 1. */
  oldStart: number
  newStart: number
  /** Hidden lines; 0 for a hunk that starts right after the previous one. */
  count: number
  /** The hunk after the gap, whose `@@` header the gap row shows; undefined for the trailing gap. */
  hunk?: number
  /** Whether the hidden lines are known (both texts were given), so the gap can open. */
  expandable: boolean
}

type DiffViewFile = {
  /** Unique within the document; the new path, or the old one for a deleted file. */
  path: string
  diff: FileDiff
  oldLines: readonly string[] | null
  newLines: readonly string[] | null
  gaps: DiffGap[]
  /** The file extension, which picks the syntax highlighter. */
  language: string
}

type DiffRow =
  | { kind: "file"; file: number; key: string }
  | { kind: "notice"; file: number; notice: DiffNotice; key: string }
  | { kind: "gap"; file: number; gap: DiffGap; key: string }
  | { kind: "line"; file: number; line: DiffLine; partner?: DiffLine; hunk: number; key: string }
  | { kind: "pair"; file: number; left?: DiffLine; right?: DiffLine; hunk: number; key: string }

type FileRows = { rows: DiffRow[]; hunkRows: number[] }

type BuildState = {
  layout: DiffLayout
  collapsed: ReadonlySet<string>
  expanded: ReadonlyMap<string, ReadonlySet<number>>
  headers: boolean
}

type DiffDocument = {
  rows: DiffRow[]
  /** Row index where each file starts. */
  fileStart: number[]
  /** Per file, the row of each hunk's first change, or -1 while the file is collapsed. */
  hunkRows: number[][]
  /** Longest line in characters (tabs as 4), for the width of an unwrapped view. */
  longest: number
  /** The highest line number, for the width of the gutter. */
  maxLine: number
}

function lastOld(hunk: DiffHunk) {
  return hunk.oldLines === 0 ? hunk.oldStart : hunk.oldStart + hunk.oldLines - 1
}

function lastNew(hunk: DiffHunk) {
  return hunk.newLines === 0 ? hunk.newStart : hunk.newStart + hunk.newLines - 1
}

function gapsOf(diff: FileDiff, oldLines: readonly string[] | null) {
  const expandable = oldLines !== null
  const gaps: DiffGap[] = []
  let oldEnd = 0
  let newEnd = 0
  diff.hunks.forEach((hunk, index) => {
    const first = hunk.oldLines === 0 ? hunk.oldStart + 1 : hunk.oldStart
    gaps.push({
      id: index,
      oldStart: oldEnd + 1,
      newStart: newEnd + 1,
      count: first - oldEnd - 1,
      hunk: index,
      expandable,
    })
    oldEnd = lastOld(hunk)
    newEnd = lastNew(hunk)
  })
  if (oldLines && diff.hunks.length > 0 && oldLines.length > oldEnd) {
    gaps.push({
      id: diff.hunks.length,
      oldStart: oldEnd + 1,
      newStart: newEnd + 1,
      count: oldLines.length - oldEnd,
      expandable,
    })
  }
  return gaps
}

function extensionOf(path: string) {
  const name = path.slice(path.lastIndexOf("/") + 1)
  const dot = name.lastIndexOf(".")
  return dot > 0 ? name.slice(dot + 1).toLowerCase() : ""
}

/** Wraps parsed or computed file diffs for the view: paths, gaps and the lines each side has. */
function toViewFiles(diffs: readonly FileDiff[]): DiffViewFile[] {
  const seen = new Map<string, number>()
  return diffs.map((diff) => {
    let path = diff.newPath ?? diff.oldPath ?? ""
    const repeat = seen.get(path) ?? 0
    seen.set(path, repeat + 1)
    if (repeat > 0) path = `${path} (${String(repeat + 1)})`
    const oldLines = diff.oldText === undefined ? null : splitLines(diff.oldText)
    const newLines = diff.newText === undefined ? null : splitLines(diff.newText)
    return { path, diff, oldLines, newLines, gaps: gapsOf(diff, newLines && oldLines), language: extensionOf(path) }
  })
}

const expandedLines = new WeakMap<DiffGap, DiffLine[]>()

/** The unchanged lines a gap hides, made once per gap. */
function gapLines(file: DiffViewFile, gap: DiffGap) {
  let lines = expandedLines.get(gap)
  if (!lines) {
    lines = []
    for (let offset = 0; offset < gap.count; offset++) {
      const text = file.newLines?.[gap.newStart - 1 + offset] ?? file.oldLines?.[gap.oldStart - 1 + offset] ?? ""
      lines.push({ kind: "context", text, oldLine: gap.oldStart + offset, newLine: gap.newStart + offset })
    }
    expandedLines.set(gap, lines)
  }
  return lines
}

function noticeOf(diff: FileDiff): DiffNotice | null {
  if (diff.binary) return "binary"
  if (diff.tooLarge) return "too-large"
  if (diff.hunks.length === 0) return "unchanged"
  return null
}

function pushLines(
  rows: DiffRow[],
  file: number,
  path: string,
  lines: readonly DiffLine[],
  hunk: number,
  layout: DiffLayout,
) {
  if (layout === "unified") {
    const partners = pairLines(lines)
    for (const line of lines) {
      const key = `${path}:${line.kind[0]!}${String(line.oldLine ?? 0)}:${String(line.newLine ?? 0)}`
      rows.push({ kind: "line", file, line, partner: partners.get(line), hunk, key })
    }
    return
  }
  let index = 0
  while (index < lines.length) {
    const line = lines[index]!
    if (line.kind === "context") {
      rows.push({ kind: "pair", file, left: line, right: line, hunk, key: `${path}:c${String(line.oldLine)}` })
      index++
      continue
    }
    const removed: DiffLine[] = []
    const added: DiffLine[] = []
    while (index < lines.length && lines[index]!.kind === "removed") removed.push(lines[index++]!)
    while (index < lines.length && lines[index]!.kind === "added") added.push(lines[index++]!)
    for (let k = 0; k < Math.max(removed.length, added.length); k++) {
      const left = removed[k]
      const right = added[k]
      const key = `${path}:p${String(left?.oldLine ?? 0)}:${String(right?.newLine ?? 0)}`
      rows.push({ kind: "pair", file, left, right, hunk, key })
    }
  }
}

function buildFileRows(files: readonly DiffViewFile[], index: number, state: BuildState): FileRows {
  const file = files[index]!
  const rows: DiffRow[] = []
  const hunkRows: number[] = []
  if (state.headers) rows.push({ kind: "file", file: index, key: `${file.path}:file` })
  if (state.collapsed.has(file.path)) return { rows, hunkRows: file.diff.hunks.map(() => -1) }
  const notice = noticeOf(file.diff)
  if (notice) {
    rows.push({ kind: "notice", file: index, notice, key: `${file.path}:notice` })
    return { rows, hunkRows }
  }
  const open = state.expanded.get(file.path)
  const showGap = (gap: DiffGap) => {
    if (open?.has(gap.id)) {
      pushLines(rows, index, file.path, gapLines(file, gap), gap.hunk ?? -1, state.layout)
      return
    }
    if (gap.count > 0 || gap.hunk !== undefined) {
      rows.push({ kind: "gap", file: index, gap, key: `${file.path}:gap${String(gap.id)}` })
    }
  }
  file.diff.hunks.forEach((hunk, hunkIndex) => {
    const gap = file.gaps.find((candidate) => candidate.hunk === hunkIndex)
    if (gap) showGap(gap)
    const first = hunk.lines.findIndex((line) => line.kind !== "context")
    hunkRows.push(rows.length + Math.max(0, first))
    pushLines(rows, index, file.path, hunk.lines, hunkIndex, state.layout)
  })
  const trailing = file.gaps.find((gap) => gap.hunk === undefined)
  if (trailing) showGap(trailing)
  return { rows, hunkRows }
}

function signature(file: DiffViewFile, state: BuildState) {
  const open = state.expanded.get(file.path)
  return `${state.layout}|${String(state.headers)}|${String(state.collapsed.has(file.path))}|${open ? [...open].join(",") : ""}`
}

function maxLineOf(file: DiffViewFile) {
  const last = file.diff.hunks.at(-1)
  return Math.max(
    file.oldLines?.length ?? 0,
    file.newLines?.length ?? 0,
    last ? lastOld(last) : 0,
    last ? lastNew(last) : 0,
  )
}

function longestOf(file: DiffViewFile) {
  let longest = 0
  const measure = (text: string) => {
    if (text.length + 3 * 8 < longest) return
    let width = 0
    for (const char of text) width += char === "\t" ? 4 : 1
    if (width > longest) longest = width
  }
  for (const hunk of file.diff.hunks) for (const line of hunk.lines) measure(line.text)
  for (const line of file.newLines ?? []) measure(line)
  return longest
}

/**
 * Builds the rows of the whole document, one list for every file, so one virtualizer scrolls it. Each file's rows
 * are cached by the state that shapes them: collapsing or expanding one file rebuilds that file only.
 */
function createDocumentBuilder() {
  const cache = new WeakMap<DiffViewFile, { signature: string; rows: FileRows }>()
  const widths = new WeakMap<DiffViewFile, { longest: number; maxLine: number }>()
  return (files: readonly DiffViewFile[], state: BuildState): DiffDocument => {
    const rows: DiffRow[] = []
    const fileStart: number[] = []
    const hunkRows: number[][] = []
    let longest = 0
    let maxLine = 0
    files.forEach((file, index) => {
      const key = signature(file, state)
      let entry = cache.get(file)
      if (!entry || entry.signature !== key) {
        entry = { signature: key, rows: buildFileRows(files, index, state) }
        cache.set(file, entry)
      }
      let width = widths.get(file)
      if (width === undefined) {
        width = { longest: longestOf(file), maxLine: maxLineOf(file) }
        widths.set(file, width)
      }
      longest = Math.max(longest, width.longest)
      maxLine = Math.max(maxLine, width.maxLine)
      const start = rows.length
      fileStart.push(start)
      hunkRows.push(entry.rows.hunkRows.map((row) => (row < 0 ? -1 : row + start)))
      for (const row of entry.rows.rows) rows.push(row)
    })
    return { rows, fileStart, hunkRows, longest, maxLine }
  }
}

/** The text find in page searches in a row: its lines, and the lines a closed gap or file hides. */
function findableOf(files: readonly DiffViewFile[], row: DiffRow, collapsed: ReadonlySet<string>): string[] {
  const file = files[row.file]!
  switch (row.kind) {
    case "file":
      if (!collapsed.has(file.path)) return [file.path]
      return [file.path, file.diff.hunks.flatMap((hunk) => hunk.lines.map((line) => line.text)).join("\n")]
    case "gap":
      return row.gap.expandable
        ? [
            gapLines(file, row.gap)
              .map((line) => line.text)
              .join("\n"),
          ]
        : [""]
    case "line":
      return [row.line.text]
    case "pair":
      return [row.left?.text ?? "", row.right?.text ?? ""]
    default:
      return [""]
  }
}

export { createDocumentBuilder, findableOf, gapLines, toViewFiles }
export type { BuildState, DiffDocument, DiffGap, DiffLayout, DiffNotice, DiffRow, DiffViewFile }

import type { DiffRow } from "@/components/ui/diff-view-model"

/** Row heights in px. Rows aren't measured while lines don't wrap: each measurement lays the page out. */
type DiffMetrics = { line: number; gap: number; header: number; notice: number }

const defaultMetrics: DiffMetrics = { line: 20, gap: 36, header: 58, notice: 36 }

// Row heights the theme gives, read once per viewport: a file header holds an icon button between two inline gaps and
// two borders, after a gap from the file above; gap and notice rows fit a small button.
const heights = {
  header: "calc(var(--control-height) + 2 * var(--gap-inline) + 2px + var(--gap-items))",
  gap: "calc(max(var(--control-height-sm), 1lh) + 4px)",
}

function probe(el: HTMLElement, height: string) {
  const node = el.ownerDocument.createElement("div")
  node.style.cssText = `position:absolute;visibility:hidden;height:${height}`
  el.append(node)
  const value = node.getBoundingClientRect().height
  node.remove()
  return value
}

function readMetrics(el: HTMLElement): DiffMetrics {
  const line = Number.parseFloat(getComputedStyle(el).lineHeight)
  const gap = probe(el, heights.gap)
  const header = probe(el, heights.header)
  return {
    line: line > 0 ? line : defaultMetrics.line,
    gap: gap > 0 ? gap : defaultMetrics.gap,
    header: header > 0 ? header : defaultMetrics.header,
    notice: gap > 0 ? gap : defaultMetrics.notice,
  }
}

function sameMetrics(a: DiffMetrics, b: DiffMetrics) {
  return a.line === b.line && a.gap === b.gap && a.header === b.header && a.notice === b.notice
}

function rowHeight(metrics: DiffMetrics, row: DiffRow | undefined) {
  if (row?.kind === "file") return metrics.header
  if (row?.kind === "gap") return metrics.gap
  if (row?.kind === "notice") return metrics.notice
  return metrics.line
}

export { defaultMetrics, readMetrics, rowHeight, sameMetrics }
export type { DiffMetrics }

import type { GridCell, GridFocusReason } from "@ui-sdk/core"

import type { DiffDocument, DiffLayout, DiffRow, DiffViewFile } from "@/components/ui/diff-view-model"
import type { DiffLine } from "@/lib/diff-types"

type DiffSide = "old" | "new"
type DiffLineRef = { side: DiffSide; line: number }
type DiffLineSelection = { path: string; start: DiffLineRef; end: DiffLineRef; lines: readonly DiffLine[] }
type SelectReason = "item-press" | "list-navigation" | "escape-key" | "imperative"
type SelectHandler = (selection: DiffLineSelection | null, reason: SelectReason, event?: Event) => boolean

type SelectionSource = {
  doc: () => DiffDocument
  files: () => readonly DiffViewFile[]
  layout: () => DiffLayout
  selected: () => readonly string[]
  setSelected: (keys: readonly string[]) => void
}

const lineRow = (row: DiffRow | undefined): row is Extract<DiffRow, { kind: "line" | "pair" }> =>
  row?.kind === "line" || row?.kind === "pair"

function lineAt(row: DiffRow, col: number): DiffLine | undefined {
  if (row.kind === "line") return row.line
  if (row.kind === "pair") return col === 0 ? row.left : row.right
  return undefined
}

function refOf(line: DiffLine, col: number, layout: DiffLayout): DiffLineRef {
  const side: DiffSide = layout === "split" ? (col === 0 ? "old" : "new") : line.kind === "removed" ? "old" : "new"
  return { side, line: (side === "old" ? line.oldLine : line.newLine) ?? line.oldLine ?? 0 }
}

// Line numbers are drawn by CSS on the cell, so a press on them is one left of where the code starts.
function onGutter(event: Event | undefined) {
  if (!(event instanceof MouseEvent) || !(event.target instanceof Element)) return false
  const code = event.target.closest('[role="gridcell"]')?.querySelector('[data-slot="diff-view-code"]')
  return Boolean(code && event.clientX < code.getBoundingClientRect().left)
}

const refuseNothing: SelectHandler = () => false

/**
 * The lines selected for a comment: one line from a press on its number or Enter, a range in one file and on one
 * side with Shift. The anchor is kept by row key, so expanding a gap above it doesn't move the range.
 */
function createLineSelection(source: SelectionSource) {
  let anchor: { key: string; col: number } | null = null
  let handler = refuseNothing

  const indexOfKey = (key: string) => source.doc().rows.findIndex((row) => row.key === key)

  function select(from: GridCell | null, to: GridCell | null, extend: boolean, reason: SelectReason, event?: Event) {
    if (!to) {
      anchor = null
      if (source.selected().length === 0 || handler(null, reason, event)) return
      source.setSelected([])
      return
    }
    const { rows } = source.doc()
    const anchorRow = extend && anchor ? indexOfKey(anchor.key) : -1
    const start = anchorRow >= 0 ? anchorRow : (from?.row ?? to.row)
    const target = rows[to.row]
    const first = rows[start]
    if (!target || !first || first.file !== target.file) return
    const col = to.col
    const [low, high] = start <= to.row ? [start, to.row] : [to.row, start]
    const keys: string[] = []
    const lines: DiffLine[] = []
    for (let index = low; index <= high; index++) {
      const row = rows[index]
      const line = row && lineRow(row) ? lineAt(row, col) : undefined
      if (!row || !line) continue
      keys.push(`${row.key}#${String(col)}`)
      lines.push(line)
    }
    if (lines.length === 0) return
    const layout = source.layout()
    const selection: DiffLineSelection = {
      path: source.files()[target.file]!.path,
      start: refOf(lines[0]!, col, layout),
      end: refOf(lines.at(-1)!, col, layout),
      lines,
    }
    if (handler(selection, reason, event)) return
    if (anchorRow < 0) anchor = { key: first.key, col }
    source.setSelected(keys)
  }

  return {
    select,
    onSelect(next: SelectHandler) {
      handler = next
    },
    moved(cell: GridCell, from: GridCell | null, shift: boolean, reason: GridFocusReason, event?: Event) {
      if (shift) select(from, cell, true, reason === "item-press" ? "item-press" : "list-navigation", event)
      else if (reason === "item-press" && onGutter(event)) select(cell, cell, false, "item-press", event)
    },
  }
}

export { createLineSelection, lineAt, lineRow }
export type { DiffLineRef, DiffLineSelection, DiffSide, SelectHandler, SelectReason }

import { createVirtualizer, type GridCell, type GridFocus, type PrimitiveContext, type VirtualItem } from "@ui-sdk/core"

import { createDiffSyntax } from "@/components/ui/diff-syntax"
import { defaultMetrics, readMetrics, rowHeight, sameMetrics } from "@/components/ui/diff-view-metrics"
import {
  createDocumentBuilder,
  findableOf,
  type DiffDocument,
  type DiffLayout,
  type DiffRow,
  type DiffViewFile,
} from "@/components/ui/diff-view-model"
import {
  createLineSelection,
  lineRow,
  type DiffLineRef,
  type DiffLineSelection,
  type DiffSide,
} from "@/components/ui/diff-view-selection"
import { intraline } from "@/lib/diff-intraline"
import type { DiffLine, IntralineMode, IntralineRanges } from "@/lib/diff-types"

type DiffViewState = {
  layout: DiffLayout
  wrap: boolean
  viewed: readonly string[]
  collapsed: readonly string[]
  active: GridCell | null
  selected: readonly string[]
  version: number
}

type DiffSnapshot = {
  doc: DiffDocument
  files: readonly DiffViewFile[]
  items: readonly VirtualItem[]
  size: number
  layout: DiffLayout
  wrap: boolean
  syntax: number
}

type DocumentOptions = {
  files?: readonly DiffViewFile[]
  headers?: boolean
  intraline?: IntralineMode | false
  findable?: boolean
  onLineSelect?: unknown
}

type DocumentContext = Pick<
  PrimitiveContext<DocumentOptions, DiffViewState, string>,
  "store" | "options" | "onOptions" | "onDestroy"
> & {
  options: () => DocumentOptions
}

const preferredCol = (row: DiffRow) => (row.kind === "pair" && row.right ? 1 : 0)

/** The state behind a DiffView: rows, the virtualizer, syntax, selection and moves. One per instance. */
function createDiffDocument(context: DocumentContext) {
  const build = createDocumentBuilder()
  const expanded = new Map<string, Set<number>>()
  const listeners = new Set<() => void>()
  const ranges = new WeakMap<DiffLine, IntralineRanges | null>()
  let files = context.options().files ?? []
  let collapsedSet: ReadonlySet<string> = new Set(context.store.get().collapsed)
  let doc = buildDoc()
  let syntaxVersion = 0
  let grid: GridFocus | null = null
  let viewport: HTMLElement | null = null
  let metrics = defaultMetrics

  function buildDoc() {
    const state = context.store.get()
    collapsedSet = new Set(state.collapsed)
    return build(files, {
      layout: state.layout,
      collapsed: collapsedSet,
      expanded,
      headers: context.options().headers ?? false,
    })
  }

  const findable = context.options().findable !== false
  const virtual = createVirtualizer({
    count: () => doc.rows.length,
    estimate: (index) => rowHeight(metrics, doc.rows[index]),
    key: (index) => doc.rows[index]?.key ?? String(index),
    overscan: 10,
    keep: () => {
      const active = context.store.get().active
      return active && active.row < doc.rows.length ? [active.row] : []
    },
    findable: findable ? (index) => findableOf(files, doc.rows[index]!, collapsedSet) : undefined,
  })

  const syntax = createDiffSyntax(() => {
    syntaxVersion++
    publish()
  })
  context.onDestroy(() => syntax.dispose())

  let snapshot = makeSnapshot()
  function makeSnapshot(): DiffSnapshot {
    const state = context.store.get()
    return {
      doc,
      files,
      items: virtual.items(),
      size: virtual.size(),
      layout: state.layout,
      wrap: state.wrap,
      syntax: syntaxVersion,
    }
  }
  function publish() {
    snapshot = makeSnapshot()
    for (const listener of listeners) listener()
  }

  const selection = createLineSelection({
    doc: () => doc,
    files: () => files,
    layout: () => context.store.get().layout,
    selected: () => context.store.get().selected,
    setSelected: (keys) => context.store.set({ selected: keys }),
  })

  function rebuild() {
    const { active } = context.store.get()
    const activeKey = active ? doc.rows[active.row]?.key : undefined
    doc = buildDoc()
    const row = activeKey === undefined ? -1 : doc.rows.findIndex((entry) => entry.key === activeKey)
    if (active && row !== active.row) context.store.set({ active: row < 0 ? null : { row, col: active.col } })
    virtual.refresh()
    publish()
  }

  context.store.subscribe((_live, _delivered, changed) => {
    if (changed.includes("layout") || changed.includes("collapsed")) rebuild()
    else if (changed.includes("wrap")) {
      virtual.reset()
      publish()
    }
  })
  context.onOptions((options) => {
    if (options.files === files) return
    files = options.files ?? []
    expanded.clear()
    rebuild()
  })

  // A match of find in page in a closed gap or a collapsed file opens it, so the browser can show the text.
  virtual.subscribe(() => {
    const found = virtual.items().find((item) => item.found)
    const row = found ? doc.rows[found.index] : undefined
    if (row?.kind === "gap" && row.gap.expandable) expandGap(row.file, row.gap.id)
    else if (row?.kind === "file" && collapsedSet.has(files[row.file]!.path)) setCollapsed(files[row.file]!.path, false)
    else publish()
  })

  function file(path: unknown) {
    const found = files.find((entry) => entry.path === path)
    if (!found) {
      const known = files.slice(0, 20).map((entry) => entry.path)
      throw new RangeError(`No file "${String(path)}". Files: ${known.join(", ")}${files.length > 20 ? "…" : ""}.`)
    }
    return found
  }

  function setCollapsed(path: string, collapsed: boolean) {
    const current = context.store.get().collapsed
    if (current.includes(path) === collapsed) return
    context.store.set({ collapsed: collapsed ? [...current, path] : current.filter((entry) => entry !== path) })
  }

  function expandGap(fileIndex: number, gap: number) {
    const path = files[fileIndex]!.path
    const open = expanded.get(path) ?? new Set<number>()
    if (open.has(gap)) return
    // A new set, so the builder sees the file's signature change.
    expanded.set(path, new Set([...open, gap]))
    rebuild()
  }

  function go(row: number, event?: Event) {
    const target = doc.rows[row]
    if (!target) return
    virtual.scrollToIndex(row, { align: "center" })
    const cell = { row, col: preferredCol(target) }
    const focused = globalThis.document?.activeElement
    const inside = Boolean(viewport && focused && viewport.contains(focused))
    if (grid && (event || inside)) grid.focus(cell, { reason: "imperative" })
    else context.store.set({ active: cell })
  }

  function currentRow() {
    const active = context.store.get().active
    if (active) return active.row
    const first = virtual.items().find((item) => viewport === null || item.start >= viewport.scrollTop)
    return first ? first.index - 1 : -1
  }

  return {
    subscribe(listener: () => void) {
      listeners.add(listener)
      return () => {
        listeners.delete(listener)
      }
    },
    snapshot: () => snapshot,
    rows: () => doc.rows,
    files: () => files,
    fileItems: () => files.map((entry) => ({ value: entry.path, label: entry.path })),
    syntax,
    virtual,
    attachGrid(next: GridFocus) {
      grid = next
    },
    onSelect: selection.onSelect,
    select: selection.select,
    moved: selection.moved,
    connect(el: HTMLElement) {
      viewport = el
      const next = readMetrics(el)
      if (!sameMetrics(next, metrics)) {
        metrics = next
        virtual.reset()
      }
      // The viewport is dir="ltr" for the code; headers follow the page's direction through this variable.
      el.style.setProperty("--diff-page-direction", getComputedStyle(el.parentElement ?? el).direction)
      const disconnect = virtual.connect(el, { findable })
      const resize = new ResizeObserver(() =>
        el.style.setProperty("--diff-viewport-width", `${String(el.clientWidth)}px`),
      )
      resize.observe(el)
      return () => {
        resize.disconnect()
        disconnect()
        viewport = null
      }
    },
    /** Changed words of a line against the line it pairs with, cached per pair. */
    intraline(line: DiffLine, partner: DiffLine | undefined) {
      const mode = context.options().intraline ?? "word"
      if (!partner || mode === false || line.kind === "context") return null
      let result = ranges.get(line)
      if (result === undefined) {
        const [removed, added] = line.kind === "removed" ? [line, partner] : [partner, line]
        const found = intraline(removed.text, added.text, { mode })
        ranges.set(removed, found?.old ?? null)
        ranges.set(added, found?.new ?? null)
        result = ranges.get(line) ?? null
      }
      return result
    },
    focusable(cell: GridCell) {
      const row = doc.rows[cell.row]
      if (row?.kind === "gap" || row?.kind === "line") return cell.col === 0
      if (row?.kind === "pair") return Boolean(cell.col === 0 ? row.left : row.right)
      return false
    },
    reveal: (row: number) => virtual.scrollToIndex(row),
    pageSize: () => (viewport ? Math.max(1, Math.floor(viewport.clientHeight / metrics.line) - 1) : 10),
    activate(cell: GridCell, event: KeyboardEvent) {
      const row = doc.rows[cell.row]
      if (row?.kind === "gap" && row.gap.expandable) expandGap(row.file, row.gap.id)
      else if (lineRow(row)) selection.select(cell, cell, event.shiftKey, "list-navigation", event)
    },
    setCollapsed,
    file,
    expand(path: unknown, gap: unknown) {
      const index = files.indexOf(file(path))
      const target = files[index]!.gaps.find((entry) => entry.id === gap)
      if (!target?.expandable) throw new RangeError(`File "${String(path)}" has no gap ${String(gap)} to expand.`)
      expandGap(index, target.id)
      return target.count
    },
    toggleFile(path: unknown, open?: unknown) {
      const target = file(path)
      const next = open === undefined ? !collapsedSet.has(target.path) : !open
      setCollapsed(target.path, next)
      return !next
    },
    openFile(path: unknown) {
      const target = file(path)
      setCollapsed(target.path, false)
      virtual.scrollToIndex(doc.fileStart[files.indexOf(target)]!, { align: "start" })
      return { path: target.path, additions: target.diff.additions, deletions: target.diff.deletions }
    },
    stepHunk(direction: 1 | -1, event?: Event) {
      const current = currentRow()
      const rows = doc.hunkRows.flat().filter((row) => row >= 0)
      const target = direction > 0 ? rows.find((row) => row > current) : rows.findLast((row) => row < current)
      if (target === undefined) return null
      go(target, event)
      const row = doc.rows[target]!
      return { path: files[row.file]!.path, hunk: lineRow(row) ? row.hunk : 0 }
    },
    stepFile(direction: 1 | -1, event?: Event) {
      const current = currentRow()
      const starts = doc.fileStart
      const index =
        direction > 0 ? starts.findIndex((row) => row > current) : starts.findLastIndex((row) => row < current - 1)
      if (index < 0) return null
      const start = starts[index]!
      const end = starts[index + 1] ?? doc.rows.length
      const first = doc.rows.slice(start, end).findIndex((row) => lineRow(row))
      if (first >= 0) go(start + first, event)
      virtual.scrollToIndex(start, { align: "start" })
      return { path: files[index]!.path }
    },
    hunk(path: unknown, n: unknown) {
      const target = file(path)
      const hunk = typeof n === "number" ? target.diff.hunks[n] : undefined
      if (!hunk) throw new RangeError(`"${target.path}" has hunks 0 to ${String(target.diff.hunks.length - 1)}.`)
      const { lines, ...header } = hunk
      return { path: target.path, ...header, lines: lines.map((line) => ({ ...line })) }
    },
  }
}

type DiffDocumentController = ReturnType<typeof createDiffDocument>

export { createDiffDocument }
export type { DiffDocumentController, DiffLineRef, DiffLineSelection, DiffSide, DiffSnapshot, DiffViewState }

import {
  byCell,
  createChange,
  createController,
  createGridFocus,
  definePrimitive,
  dispatch,
  selects,
  type ChangeDetails,
  type GridCell,
} from "@ui-sdk/core"

import { createDiffDocument, type DiffLineSelection } from "@/components/ui/diff-view-document"
import type { DiffLayout, DiffViewFile } from "@/components/ui/diff-view-model"
import type { IntralineMode } from "@/lib/diff-types"

type DiffViewController = {
  openFile: (path: string) => { path: string; additions: number; deletions: number } | undefined
  toggleFile: (path: string, open?: boolean) => boolean | undefined
  markViewed: (path: string, viewed?: boolean) => void
  nextHunk: () => { path: string; hunk: number } | null | undefined
  previousHunk: () => { path: string; hunk: number } | null | undefined
  nextFile: () => { path: string } | null | undefined
  previousFile: () => { path: string } | null | undefined
  expandGap: (path: string, gap: number) => number | undefined
  setLayout: (layout: DiffLayout) => void
  setWrap: (wrap: boolean) => void
  clearSelection: () => void
}

/** A handle to drive a DiffView from outside it, like a file list beside it: pass it as `controller`. */
function createDiffViewController() {
  return createController<DiffViewController>()
}

type DiffViewOptions = {
  controller?: DiffViewController
  files?: readonly DiffViewFile[]
  /** Whether each file gets a header row (path, counts, collapse, viewed). */
  headers?: boolean
  layout?: DiffLayout
  defaultLayout?: DiffLayout
  onLayoutChange?: (layout: DiffLayout, details: ChangeDetails<"item-press" | "imperative">) => void
  wrap?: boolean
  defaultWrap?: boolean
  onWrapChange?: (wrap: boolean, details: ChangeDetails<"press" | "imperative">) => void
  /** Paths marked viewed. */
  viewed?: readonly string[]
  defaultViewed?: readonly string[]
  onViewedChange?: (viewed: readonly string[], details: ChangeDetails<"press" | "imperative">) => void
  /** Paths that start collapsed. */
  defaultCollapsed?: readonly string[]
  /** A line, or a range with Shift, was selected for a comment; `null` when the selection clears. */
  onLineSelect?: (
    selection: DiffLineSelection | null,
    details: ChangeDetails<"item-press" | "list-navigation" | "escape-key" | "imperative">,
  ) => void
  intraline?: IntralineMode | false
  /** Find in page reaches lines that aren't rendered and opens collapsed gaps and files. @defaultValue true */
  findable?: boolean
}

const cellKeys = [
  "ArrowUp",
  "ArrowDown",
  "ArrowLeft",
  "ArrowRight",
  "Home",
  "End",
  "mod+Home",
  "mod+End",
  "PageUp",
  "PageDown",
  "Enter",
  "Space",
  "Escape",
] as const

function typing(target: EventTarget | null) {
  return target instanceof HTMLElement && (target.isContentEditable || /^(INPUT|TEXTAREA|SELECT)$/.test(target.tagName))
}

/**
 * A virtualized diff of one or many files: every file's rows in one list under one virtualizer, one tab stop over
 * the lines (createGridFocus), j/k and n/p between hunks and files, Shift ranges for comments, and find in page
 * through the virtualizer's findable layers, which also opens a collapsed gap or file it matches.
 */
const diffView = definePrimitive({
  name: "diff-view",
  options: {
    controller: "value",
    files: "value",
    headers: "boolean",
    layout: "string",
    defaultLayout: "string",
    onLayoutChange: "callback",
    wrap: "boolean",
    defaultWrap: "boolean",
    onWrapChange: "callback",
    viewed: "list",
    defaultViewed: "list",
    onViewedChange: "callback",
    defaultCollapsed: "list",
    onLineSelect: "callback",
    intraline: "value",
    findable: "boolean",
  },
  state: (options: DiffViewOptions) => ({
    layout: options.layout ?? options.defaultLayout ?? ("unified" as DiffLayout),
    wrap: options.wrap ?? options.defaultWrap ?? false,
    viewed: options.viewed ?? options.defaultViewed ?? ([] as readonly string[]),
    collapsed: options.defaultCollapsed ?? ([] as readonly string[]),
    active: null as GridCell | null,
    /** Selected cells, as `${rowKey}#${col}`. */
    selected: [] as readonly string[],
    version: 0,
  }),
  controlled: ["layout", "wrap", "viewed"],
  sync: (options) => ({
    ...(options.layout === undefined ? {} : { layout: options.layout }),
    ...(options.wrap === undefined ? {} : { wrap: options.wrap }),
    ...(options.viewed === undefined ? {} : { viewed: options.viewed }),
  }),
  api: (context) => {
    const change = createChange(context)
    const document = createDiffDocument(context)
    const grid = createGridFocus(context, {
      key: "active",
      rows: () => document.rows().length,
      cols: () => (context.store.get().layout === "split" ? 2 : 1),
      disabled: (cell) => !document.focusable(cell),
      reveal: (cell) => document.reveal(cell.row),
      pageSize: () => document.pageSize(),
      onMove: (cell, { from, shift, reason, event }) => document.moved(cell, from, shift, reason, event),
    })
    document.attachGrid(grid)
    document.onSelect((selection, reason, event) => dispatch(context, "onLineSelect", selection, { reason, event }))

    const setLayout = (layout: unknown, event?: Event) => {
      if (layout !== "unified" && layout !== "split")
        throw new RangeError(`Layout is "unified" or "split", not "${String(layout)}".`)
      change("layout", layout, { reason: event ? "item-press" : "imperative", event })
    }
    const setWrap = (wrap: unknown, event?: Event) => {
      change("wrap", Boolean(wrap), { reason: event ? "press" : "imperative", event })
    }
    const markViewed = (path: unknown, viewed: unknown = true, event?: Event) => {
      const file = document.file(path)
      const current = context.store.get().viewed
      const next =
        viewed === false ? current.filter((entry) => entry !== file.path) : [...new Set([...current, file.path])]
      change("viewed", next, { reason: event ? "press" : "imperative", event })
      // A file marked viewed folds away, as on a code review page; unmarking opens it again.
      if (context.store.get().viewed.includes(file.path) === (viewed !== false))
        document.setCollapsed(file.path, viewed !== false)
    }

    return {
      grid,
      document,
      subscribe: document.subscribe,
      snapshot: document.snapshot,
      connect: document.connect,
      setLayout,
      setWrap,
      markViewed,
      /** Brings a file into view, opening it if it was collapsed. */
      openFile: (path: unknown) => document.openFile(path),
      toggleFile: (path: unknown, open?: unknown) => document.toggleFile(path, open),
      nextHunk: () => document.stepHunk(1),
      previousHunk: () => document.stepHunk(-1),
      nextFile: () => document.stepFile(1),
      previousFile: () => document.stepFile(-1),
      /** One hunk's lines, read-only: `n` counts from 0 within the file. */
      getHunk: (path: unknown, n: unknown) => document.hunk(path, n),
      expandGap: (path: unknown, gap: unknown) => document.expand(path, gap),
      clearSelection: () => document.select(null, null, false, "imperative"),
      keydown(event: KeyboardEvent) {
        if (event.defaultPrevented || event.altKey || event.ctrlKey || event.metaKey || typing(event.target)) return
        const moves: Record<string, () => unknown> = {
          j: () => document.stepHunk(1, event),
          k: () => document.stepHunk(-1, event),
          n: () => document.stepFile(1, event),
          p: () => document.stepFile(-1, event),
        }
        const move = moves[event.key]
        if (!move) return
        event.preventDefault()
        move()
      },
      cellKeydown(event: KeyboardEvent, cell: GridCell) {
        if (event.key === "Escape" && context.store.get().selected.length > 0) {
          event.preventDefault()
          document.select(null, null, false, "escape-key", event)
          return
        }
        if (event.key === "Enter" || event.key === " ") {
          event.preventDefault()
          document.activate(cell, event)
          return
        }
        if (grid.keydown(event)) event.preventDefault()
      },
    }
  },
  slots: (slot) => ({
    root: slot({
      role: "group",
      attrs: (state) => ({
        "data-layout": state.layout,
        "data-wrap": state.wrap ? "" : undefined,
      }),
      on: { keydown: (event, { api }) => api.keydown(event as KeyboardEvent) },
    }),
    viewport: slot({
      selects: selects({}),
      bind: (el, { api }) => api.connect(el),
    }),
    file: slot<{ path: string }, { viewed: boolean; collapsed: boolean }>({
      props: { path: "string" },
      selects: selects({ viewed: ({ props }) => [props.path], collapsed: ({ props }) => [props.path] }),
      state: (state, { props }) => ({
        viewed: state.viewed.includes(props.path),
        collapsed: state.collapsed.includes(props.path),
      }),
      attrs: (state, { props }) => ({
        "data-viewed": state.viewed.includes(props.path) ? "" : undefined,
        "data-collapsed": state.collapsed.includes(props.path) ? "" : undefined,
      }),
    }),
    grid: slot<{ path: string }>({
      role: "grid",
      keys: { none: "Focus stays on a cell, whose keydown handles them." },
      props: { path: "string" },
      selects: selects({}),
    }),
    row: slot<{ value: string }>({
      role: "row",
      props: { value: "string" },
      selects: selects({}),
    }),
    cell: slot<{ row: number; col: number; value: string }>({
      role: "gridcell",
      focus: "roving",
      keys: [...cellKeys],
      props: { row: "number", col: "number", value: "string" },
      selects: selects({ active: byCell, selected: ({ props }) => [props.value] }),
      attrs: (state, { props, api }) => ({
        tabindex: api.grid.tabIndex(state, props),
        "data-active": api.grid.isActive(state, props) ? "" : undefined,
        "aria-selected": state.selected.includes(props.value) ? "true" : undefined,
      }),
      on: {
        keydown: (event, { api, props }) => api.cellKeydown(event as KeyboardEvent, props),
        pointerdown: (event, { api, props }) => {
          const pointer = event as PointerEvent
          if (pointer.button !== 0) return
          api.grid.focus(props, { reason: "item-press", event, shift: pointer.shiftKey })
        },
      },
      bind: (el, { api, props }) => api.grid.bind(el, props),
    }),
  }),
  agent: {
    actions: [
      "openFile",
      "toggleFile",
      "markViewed",
      "nextHunk",
      "previousHunk",
      "nextFile",
      "previousFile",
      "getHunk",
      "expandGap",
      "setLayout",
      "setWrap",
      "clearSelection",
    ],
    items: (api) => api.document.fileItems(),
  },
})

